(function () {
  // Timer wake-up, not a decision (plan 5.3 rule 1). Everything this flow acts
  // on is re-read from the platform; nothing is trusted from the timer payload
  // beyond the entity id the timer was named for.
  var p = (pol && pol.data) ? pol.data : {};
  var policyId = String((trg && trg.policy_id) || '');
  if (!policyId) { throw new Error('invoice-overdue: the timer payload carries no policy_id'); }
  var brokerId = String(p.broker_id || '');
  return {
    policy_id: policyId,
    broker_id: brokerId,
    policy_number: String(p.policy_number || ''),
    policy_status: String(p.policy_status || ''),
    // The index reads min:0 / max:0 as "not supplied" and has no negation, so
    // every filter here is a positive exact keyword match.
    invoice_filter: JSON.stringify({ conditions: [{ field: 'policy_id', keyword: policyId }] }),
    broker_filter: JSON.stringify({ conditions: [{ field: 'broker_id', keyword: brokerId || '__no_broker__' }] }),
    now: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z')
  };
})();

(function () {
  var p = (pol && pol.data) ? pol.data : {};
  var rows = (inv && inv.data && inv.data.results) ? inv.data.results : [];
  // The index can return one record twice across an update and total_hits counts
  // both, so de-duplicate by record id before deciding anything.
  var seen = {}, list = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    if (!r || !r.id || seen[r.id]) continue;
    seen[r.id] = 1; list.push(r);
  }
  var open = [];
  for (var j = 0; j < list.length; j++) {
    var d = list[j].data || {};
    if (d.payment_status === 'unpaid' || d.payment_status === 'overdue') open.push(list[j]);
  }
  open.sort(function (a, b) {
    return String((a.data || {}).due_date || '') < String((b.data || {}).due_date || '') ? -1 : 1;
  });
  var chosen = open.length ? open[0] : null;
  var cd = chosen ? (chosen.data || {}) : {};
  var nowMs = Date.now();
  var dueMs = cd.due_date ? new Date(cd.due_date).getTime() : NaN;
  var pastDue = !isNaN(dueMs) && nowMs >= dueMs;

  var brows = (brk && brk.data && brk.data.results) ? brk.data.results : [];
  var to = '', toName = '';
  for (var k = 0; k < brows.length; k++) {
    var bd = brows[k].data || {};
    if (bd.primary_contact_email) { to = String(bd.primary_contact_email); toName = String(bd.brokerage_name || bd.primary_contact_name || ''); break; }
  }
  // The recipient always resolves, so "who to tell" can never be the reason the
  // status transition is skipped.
  if (!to) { to = String(fallback || ''); toName = 'Antipodean Operations'; }

  var reasons = [];
  // Idempotency is structural: the transition ACTIVE -> OVERDUE is the guard.
  // A second fire finds OVERDUE and does nothing. There is no
  // overdue_notice_sent_at field on policy_config to gate on (reported).
  if (p.policy_status !== 'ACTIVE') reasons.push('policy_status_is_' + String(p.policy_status || 'absent'));
  if (!chosen) reasons.push('no_unpaid_or_overdue_invoice');
  if (chosen && !pastDue) reasons.push('due_date_not_reached');

  var daysOverdue = (!isNaN(dueMs)) ? Math.floor((nowMs - dueMs) / 86400000) : 0;
  return {
    should_act: reasons.length === 0,
    skip_reasons: reasons,
    policy_id: String((trg && trg.policy_id) || ''),
    policy_number: String(p.policy_number || ''),
    policy_status_before: String(p.policy_status || ''),
    invoice_id: chosen ? String(chosen.id) : '',
    invoice_number: String(cd.invoice_number || ''),
    invoice_status_before: String(cd.payment_status || ''),
    due_date: String(cd.due_date || ''),
    void_deadline: String(cd.void_deadline || ''),
    amount_due: Number(cd.amount_due || 0),
    amount_due_text: (Number(cd.amount_due || 0)).toFixed(2),
    days_overdue: daysOverdue,
    days_overdue_text: String(daysOverdue),
    notice_to: to,
    notice_to_name: toName,
    invoice_candidates: list.length,
    assessed_at: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z')
  };
})();
